import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { preparePhoto, uploadToSignedUrl } from "./photo-image";
import { PHOTO_ERRORS, PHOTO_MAX_BYTES } from "./product-photo";

/*
 * Generated by /ship test coverage audit.
 * jsdom no tiene createImageBitmap ni canvas: se reemplazan en el test (no en el código)
 * por lo que devuelve el navegador. El decodificado real y el EXIF los prueba el E2E
 * (Chromium); acá, lo que el E2E no puede: el navegador que no codifica WebP (Safari).
 */

const file = new File(["foto"], "foto.jpg", { type: "image/jpeg" });

/** toBlob como un navegador: `encoded(type)` decide qué blob devuelve para cada tipo pedido. */
function stubCanvas(encoded: (type: string) => Blob | null) {
  const context = { fillStyle: "", fillRect: vi.fn(), drawImage: vi.fn() };
  vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(context as never);
  const toBlob = vi
    .spyOn(HTMLCanvasElement.prototype, "toBlob")
    .mockImplementation((callback: BlobCallback, type?: string) => callback(encoded(type ?? "image/png")));
  return { context, toBlob };
}

beforeEach(() => {
  vi.stubGlobal(
    "createImageBitmap",
    vi.fn(async () => ({ width: 4000, height: 3000, close: vi.fn() })),
  );
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});

describe("preparePhoto", () => {
  // Value: protects=on a browser without WebP encoding (Safari) the photo is re-encoded as JPEG, a type the bucket accepts;
  // fails_when=the blob.type check is dropped/changed to `!blob`, so Safari uploads PNG and requestPhotoUpload rejects it;
  // why_new=E2E runs only Chromium (desktop + Pixel 7) and ProductPhotoField.test mocks preparePhoto; seam=none;
  // no_claim=real Safari canvas behavior (simulated: toBlob answers PNG when asked for WebP, as the spec allows)
  it("si el navegador no codifica WebP (devuelve PNG), usa JPEG", async () => {
    const { toBlob } = stubCanvas((type) =>
      type === "image/webp" ? new Blob(["png"], { type: "image/png" }) : new Blob(["jpg"], { type }),
    );

    const prepared = await preparePhoto(file, "#202226");

    expect(prepared.ok && prepared.blob.type).toBe("image/jpeg");
    expect(toBlob.mock.calls.map((call) => call[1])).toEqual(["image/webp", "image/jpeg"]);
  });

  // Value: protects=a photo still over the 5 MiB bucket limit after resizing is rejected in the browser with tooBig, before any upload;
  // fails_when=the PHOTO_MAX_BYTES check is removed or inverted, so the admin gets a generic upload error from Storage instead;
  // why_new=no test reaches the size branch (component test mocks preparePhoto; E2E fixtures are tiny); seam=none;
  // no_claim=that real photos can exceed the limit at 1600 px (encoder output simulated)
  it("si después de achicarla sigue pesando más que el bucket, lo dice y no devuelve la foto", async () => {
    stubCanvas((type) => new Blob([new Uint8Array(PHOTO_MAX_BYTES + 1)], { type }));

    await expect(preparePhoto(file, "#202226")).resolves.toEqual({ ok: false, message: PHOTO_ERRORS.tooBig });
  });
});

describe("uploadToSignedUrl", () => {
  // Value: protects=a rejected PUT (4xx/5xx) or a dropped connection reports failure, and the PUT carries the blob's type without upsert;
  // fails_when=response.ok is ignored (UI moves on to savePhoto and shows "Elegila de nuevo") or content-type/x-upsert headers change;
  // why_new=ProductPhotoField.test mocks this function and the E2E only exercises a successful upload; seam=none;
  // no_claim=Supabase Storage's real response codes or its MIME check (fetch stubbed at the global boundary)
  it("devuelve false si Storage rechaza el PUT o la red se corta; manda el tipo de la foto sin pisar", async () => {
    const blob = new Blob(["x"], { type: "image/webp" });
    const fetchMock = vi.fn().mockResolvedValueOnce(new Response(null, { status: 400 }));
    vi.stubGlobal("fetch", fetchMock);

    await expect(uploadToSignedUrl("http://storage/sign", blob)).resolves.toBe(false);
    expect(fetchMock).toHaveBeenCalledWith("http://storage/sign", {
      method: "PUT",
      // Nombre único por subida: la caché larga e inmutable es segura (decisión de /ship D2).
      headers: { "content-type": "image/webp", "cache-control": "public, max-age=31536000, immutable", "x-upsert": "false" },
      body: blob,
    });

    fetchMock.mockRejectedValueOnce(new TypeError("Failed to fetch"));
    await expect(uploadToSignedUrl("http://storage/sign", blob)).resolves.toBe(false);

    fetchMock.mockResolvedValueOnce(new Response(null, { status: 200 }));
    await expect(uploadToSignedUrl("http://storage/sign", blob)).resolves.toBe(true);
  });
});
